def down_the_tree(i, c, depth=0):
    last = c[i][0]
    while i:
        if i % 2 == 1:
            i = (i // 2) + 1
            if i == last:
                return
            if depth > c[i-1][-1]:
                c[i-1][-1] = 1
            elif depth == c[i-1][-1]:
                c[i-1][-1] += 1
        else:
            i = i // 2
            if i == last:
                return
            if depth < c[i-1][-1]:
                c[i-1][-1] = c[i][0]
                if depth == c[i][-1]:
