    x1, y1, dx1, dy1, s1 = car1
    x2, y2, dx2, dy2, s2 = car2

    while calculate_distance(x1 + (dx1 * t), y1 + (dy1 * t), x2 + (dx2 * t), y2 + (dy2 * t)) > 1e-6:
        t += 0.01  # Iterate slightly further and check again
