import math

def generate_prime_numbers(limit):
    sieve = [True] * (limit+1)
    sieve[0] = sieve[1] = False
    for x in range(2, int(math.sqrt(limit)) + 1):
        if sieve[x]:
            for y in range(x*x, limit, x):
                sieve[y] = False
    return [x for x in range(2, limit + 1) if sieve[x]]

def are_positions_valid(n, f):
    for i in range(1, n+1):
        if f in [i*2-1, i*2, i*3-2*i+1, i*3-3*i+2, i*4-4*i+1, i*i-i+1, i*i-1, i*i+1, i*i+3*i+1, i*i+3*i-1, i*i+4*i+1, i*i+4*i-1, i*i+5*i+1, i*i+5*i-1]:
            return False
    return True

def stone_game_winner(row, f):
    non_primes = set()
    for i in row:
        if i != -999:
            if i % 2 == 0:
                non_primes.remove(i)
    primes = sorted([x for x in row if x % 2 != 0])

    round_prime = 2
    non_prime_counter = 0
    move_winner = -1

    for now_row_prime in primes:
        if non_prime_counter <= non_primes[-1]:
            opponent_move = non_primes.pop()
            move_winner += now_row_prime + opponent_move
            if non_prime_counter + 1 == len(non_primes):
                non_prime_counter = 1
            else:
                non_prime_counter += 1
        else:
            opponent_move = non_prime_counter
            move_winner += now_row_prime + opponent_move

        if non_prime_counter >= f:
            non_prime_counter = f
        else:
            non_prime_counter += 1
        non_primes.insert(round_prime * f - 1, non_prime_counter)
        round_prime *= 2
        move_winner += f
        while move_winner < 10**5:
            force_bob = sum([now_row_prime - x for x in non_prime_counter + 1])
            if force_bob % 2 == 0:
                force_bob = -force_bob
            if not (now_row_prime - 2 - force_bob <= 0 or force_bob <= 0):
                move_winner += force_bob
    return move_winner

