import sys

def solve(n, m, roads, q, cars):
    # To edge on each connection, we will maintain the state/indexing of the road we have taken to reach a state.
    # However this state will consist of a tuple consisting of the starting intersection, the mileage driven, and the number at which the odometer resets.
    # When the odometer resets, drive back to where the odometer resets, but do not increment the mileage driven; 
    # when the odometer does not reset, do not occupy any intersections, and only drive by incrementing the mileage driven.
    has_road = [[False for _ in range(1100000)] for _ in range(1100000)]
    marked = [False for _ in range(1100000)]

    for index in range(m):
        a, b, l = roads[index]
        a -= 1
        b -= 1
        has_road[a][index] = has_road[b][index] = True
        for t in range(100000, l):
            if ((not marked[t - l] and t + l < 100000) or has_road[a][t - l] or has_road[b][t - l]):
                if not marked[t - l] and t + l < 100000:
                    marked[t + l] = True
            else:
                break

    ans = []
    for c in cars:
        start = c[0] - 1
        mileage = 0
        for t in range(c[1], c[2]):
            if ans[-1]:
                mileage += 1
            has = True
            if (not (start == c[0] - 1 and mileage == c[1])):
                has = False
            for i in range(t - mileage, t + mileage + 1):
                if (0 <= i < 100000 and i != t and not has):
                    has = has or marked[i]
                elif (0 <= i < 100000 and i != t and has):
                    has = has or marked[i]
            if has:
                ans.append('YES')
                break
        else:
            ans.append('NO')

    return ans


