from collections import defaultdict

def score_of_subtree(tree, subtree_size):
    if subtree_size == 0:
        return 0
    elif subtree_size == 1:
        return 1
    elif subtree_size == 2:
        return 2

    neighbors = defaultdict(list)
    for a, b in tree:
        neighbors[b].append(a)
        neighbors[a].append(b)

    # Check all subtrees with size up to k
    max_score = 1
    for size in range(3, k + 1):
        max_score = max(max_score, max(length for leaf in tree for length in range(score_tree(size, leaf, neighbors)))
                        for leaf in tree)
    return max_score

def score_tree(size, root, neighbors):
    if size != 1:
        max_length = 0
        for neighbor in neighbors[root]:
            child_score = score_tree(size - 1, neighbor, neighbors)
            if child_score >= 2:
                max_length = max(max_length, max_length_leaf(child_score, neighbors))
        return max_length + size
    else:
        return 1

def max_length_leaf(length, neighbors):
    max_length = length
    for neighbor in neighbors[root]:
        current_length = score_tree(length - 1, neighbor, neighbors)
        max_length = max(max_length, max_length_leaf(current_length, neighbors))
    return max_length

