def build_graph(n, edges):
    graph = [[] for _ in range(n)]
    for i, j in edges:
        if i < j:
            graph[i].append((j, 0))  # (j, 0) represents the edge is not in the set
            graph[j].append((i, 1))  # (i, 1) represents the edge is not in the set
    return graph

def get_neighbors_and_set(graph, vertex):
    neighbors = [(neighbor[0], vertex & neighbor[1]) for neighbor in graph[vertex]]
    return neighbors

def count_connected_components(vertices, edges, graph):
    components = {}
    for vertex, set_flag in vertices:
        current_set = tuple(vertices).intersection(set_flag)
        if current_set not in components:
            components[current_set] = 1
        for neighbor, set_flag in get_neighbors_and_set(graph, vertex):
            if neighbors[neighbor] != tuple(set_flag):
                edge_exists_in_set_flag = neighbors[neighbor][1] & current_set
                if edge_exists_in_set_flag == 0:
                    components[current_set + (neighbor,)] = components[current_set] + 1
    return sum([count for name, count in components.items()])

