from typing import List

def update_weight(arr: List[int], queries: List[List[int]]) -> None:
    """
    Updates the array based on the given queries and prints the weight of the array after each update.
    """
    n, q = len(arr), len(queries)
    weights = [1] * n  # Initialize weights as all initially 1 (each element is a separate component)

    idx = sorted(range(n), key=lambda i: arr[i])

    for pos, x in queries:
        if arr[pos] > x:
            weights[pos] = 1  # The new element will make the component containing this element be one connected component larger
        else:
            for i in range(pos, -1, -1):
                if arr[i] > x:
                    weights[i] = 0  # Converting the adjacent element from 'greater' to 'equal' makes it part of the same component
                else:
                    weights[i] -= 1  # All smaller elements in arr[i] and arr[i-1] convert this element to 'lower' in some components

            for i in range(pos + 1, n):
                if arr[i] > x:
                    weights[i] = 0  # Converting the next element from 'greater' to 'equal' makes it part of the same component

    print(" ".join(map(str, weights)))

