def decompress_sequence(seq):
    stack = []
    for i, char in enumerate(seq):
        if char.isdigit() or ('A' <= char <= 'Z'):
            stack.append(int(char))
        else:
            stack[-2] *= 10
            stack[-2] += int(char)
        # Ensure the stack has at least two levels for subtraction
        while len(stack) > 2:
            stack.pop()
            stack.pop()
    # Check for remaining items and apply appropriate operations
    while len(stack) > 2:
        right = stack.pop()
        left = stack.pop()
        if left // right >= 1:
            stack.pop()
            stack[-1] = left - right * (left // right)
    seq = []
    while stack:
        seq.append(str(stack.pop()))
    seq.reverse()
    return ''.join(seq)

