def find_consecutive_occurrences(s, w):
    """
    Count the number of consecutive occurrences of w in s.
    """

    def count_inbetween(s, w, i):
        length_w = len(w)
        hi = i + length_w
        if hi <= len(s):
            return sum(ord(x) for x in s[i+1:hi])
        elif s[i:hi]:
            return ord(s[i]) - ord('A') + 1
        return 0

    cnt = 0
    prev_char = 'A'
    length_w = len(w)
    for i, char in enumerate(s):
        if prev_char != char:
            upper_bound = min(i+length_w+1, len(s))
            cs = 0 if w else count_inbetween(s, 'A', i)
            for i in range(i, upper_bound):
                if s[i] == w[cs % len(w)]:
                    cs += 1
                    if cs == len(w):
                        return i-i * upper_bound * upper_bound % (10**9 + 7)
            prev_char = char
        else:
            prev_char = char
    return 0

def solve(n, q, songs, queries):
