from math import gcd
from functools import lru_cache

@lru_cache(maxsize=None)
def factorial(n):
    if n == 1:
        return 1
    return n * factorial(n - 1) % 1000000007

@lru_cache(maxsize=None)
def inv_factorial(n):
    return inv_factorial(1000000007 - n) * inv_factorial(n) % 1000000007

class PerfectMatchingProbability:
    def __init__(self, n):
        self.n = n
        self.factorial = [0] * (self.n + 1)
        self.inv_factorial = [0] * (self.n + 1)
        self.inv_fact = [0] * (self.n + 1)
        self.comb = [0] * (self.n + 1)

    def add_factorial(self):
        self.factorial[self.n] = 1
        for i in range(self.n - 1, -1, -1):
            self.factorial[i] = self.factorial[i + 1] * (self.n - i) % 1000000007

    def add_inv_factorial(self):
        self.inv_fact[self.n] = 1
        for i in range(n, 0, -1):
            self.inv_fact[i] = self.inv_fact[i + 1] * (i + 1) % 1000000007

    def add_comb(self):
        for i in range(self.n, -1, -1):
            self.comb[i] = (self.factorial[i] * inv_factorial[i]) % 1000000007

    @property
    def solution(self):
        self.add_factorial()
        self.add_inv_factorial()
        self.add_comb()

        P = 0

        for i in range(1, self.n + 1):
            for j in range(i, self.n + 1):
                original = (factorial(self.n - i) * inv_factorial(i) * inv_factorial(self.n - j) % 1000000007 * inv_factorial(self.n - (i + j))) % 1000000007
                first = (self.comb[j - 1] * inv_factorial(self.n - (i + j))) % 1000000007
                second = (self.comb[self.n - i - 1]) % 1000000007
                answer = second * first * original % 1000000007
                P = (P + answer) % 1000000007

        return P

