import math

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def get_possible_moves(f, board):
    possible = []
    for i in range(len(board)):
        if (f != i and i - f in board) or (f != i and i != 2 and i == (f + 1) / 2):
            possible.append((i, f))
    return possible

def is_valid_move(board, move, f):
    next_pos = move + move
    return board[move] < board[next_pos]

def start_game(f, board):
    alice_wins = 0
    bob_wins = 0
    for i in board:
        possible_moves = get_possible_moves(f, i)
        alice_wins += len(possible_moves)
        bob_wins += len(possible_moves)
    if alice_wins > bob_wins:
        return "Alice"
    else:
        return "Bob"

