from math import gcd
from functools import reduce
from operator import mul
import sys

def find_gcd(*numbers):
    return reduce(gcd, numbers)

def lcm(a, b):
    return a * b // gcd(a, b)

def find_overlapping_point(x1, y1, dx1, dy1, s1, x2, y2, dx2, dy2, s2):
    d = (x1 - x2) * (dx2 - dx1) * (dy1 - dy2) + (y1 - y2) * (dy2 - dy1) * (dx1 - dx2)
    if d == 0:
        return float('inf')
    m = (dx1 * dx1 + dy1 * dy1) * (dx2 * dx2 + dy2 * dy2) - (dx1 * dx2 + dy1 * dy2) ** 2
    n = (dx1 * dx1 + dy1 * dy1) * (x2 - x1) + (dx2 * dx2 + dy2 * dy2) * (y2 - y1)
    r = -m / n
    p = -s1 * s2 * (x2 - x1) - s1 * r - s2 * r
    q = s1 * s2 * s2 * (s1 * s2 * m + (s1 * r + s2 * r) ** 2)
    return lcm(abs(r + p), q) / p

def find_min_duration(cars):
    cars_sorted = sorted(cars, key=lambda x: find_overlapping_point(*x[:4], *x[4:]))

    min_duration = float('inf')
    for i in range(len(cars_sorted)):
        for j in range(i, len(cars_sorted)):
            overlap = find_overlapping_point(*cars_sorted[i][:4], *cars_sorted[j][:4], *cars_sorted[j][4:])
            if overlap == float('inf'):
                continue
            duration = overlap / cars_sorted[i][1]
            if duration < min_duration:
                min_duration = duration
    return min_duration

