    queue = [(0, s)]
    while queue:
        curr_dist, node = heappop(queue)
        if curr_dist > distance[node]:
            continue
        for neighbor in graph[node]:
            if curr_dist + 1 < distance[neighbor]:
                distance[neighbor] = curr_dist + 1
                heappush(queue, (curr_dist + 1, neighbor))
    return distance

