import sys

def max_contiguous_sum(A, max_before, memo):
    if not A:
        return 0
    key = tuple(A)
    if key in memo:
        return memo[key]
    max_sum, current_sum = max_before[key], max_before[key]
    for i in range(1, len(A)+1):
        current_sum = max(max_sum, current_sum + A[-i])
        max_sum = max(max_sum, current_sum)
        memo[key] = max(max_sum, current_sum)
    memo[key] = max(max_before[key], max_before[key])
    return max(max_before[key], max_before[key])

def chef_problem(num_tests):
    for _ in range(num_tests):
        N = int(input())
        A = list(map(int, input().split()))
        max_before = {tuple([A[0]]): A[0]}
        for i in range(1, N):
            A.insert(0, A.pop())
            max_contiguous_sum(A, max_before, max_before)
        print(max_before[tuple(A)])

